"use client";

import { forwardRef, useEffect, useState, type CSSProperties, type HTMLAttributes } from "react";
import { videoTextDefaults, type VideoTextSpecProps } from "../generated/video-text.types";
import { cx } from "../utils/cx";
import { useReducedMotion } from "../utils/motion";

export interface VideoTextProps
  extends VideoTextSpecProps,
    Omit<HTMLAttributes<HTMLSpanElement>, keyof VideoTextSpecProps | "className" | "children"> {
  className?: string;
}

/**
 * Large text that shows a video through its letters. You supply the video (src); none is bundled. The
 * text is real text. Until the video has loaded, and whenever it is paused, blocked by reduced motion
 * or fails, the letters show the fallback gradient, painted with background-clip. The video is added
 * after mount, so the server HTML has no video and nothing is fetched without JavaScript.
 */
export const VideoText = forwardRef<HTMLSpanElement, VideoTextProps>(function VideoText(
  { children, src, poster, fallback = videoTextDefaults.fallback, tone = videoTextDefaults.tone, isPaused = videoTextDefaults.isPaused, className, style, ...rest },
  ref,
) {
  const reduced = useReducedMotion();
  const [mounted, setMounted] = useState(false);
  const [ready, setReady] = useState(false);
  useEffect(() => setMounted(true), []);
  const useVideo = Boolean(src) && mounted && !isPaused && !reduced;
  useEffect(() => {
    if (!useVideo) setReady(false);
  }, [useVideo]);

  return (
    <span
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      data-rdm-video={useVideo && ready ? "on" : undefined}
      data-tone={tone}
      className={cx("rdm-video-text", className)}
      style={{ "--rdm-fb": fallback, ...style } as CSSProperties}
    >
      {useVideo ? (
        <video
          aria-hidden="true"
          tabIndex={-1}
          className="rdm-video-text-video"
          src={src}
          poster={poster}
          autoPlay
          loop
          muted
          playsInline
          preload="metadata"
          disablePictureInPicture
          onLoadedData={() => setReady(true)}
          onError={() => setReady(false)}
        />
      ) : null}
      <span className="rdm-video-text-label">{children}</span>
    </span>
  );
});

// Generated by rdloom codegen from specs/video-text.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const videoTextToneValues = ["light", "dark"] as const;

/** Large text that shows a video you supply through its letters. The text stays real text; a gradient fallback shows until the video plays. */
export interface VideoTextSpecProps {
  /**
   * The text.
   */
  children: string;
  /**
   * URL of the video you supply. Without it the fallback gradient is shown.
   */
  src?: string;
  /**
   * URL of a poster image for the video.
   */
  poster?: string;
  /**
   * CSS background shown through the letters until the video plays, or instead of it.
   * @default "linear-gradient(120deg, var(--rd-color-action-primary), var(--rd-color-feedback-info))"
   */
  fallback?: string;
  /**
   * The surface the video box sits on: light draws a white box, dark a black one.
   * @default "light"
   */
  tone?: "light" | "dark";
  /**
   * Pauses the video and shows the fallback gradient instead. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
}

export const videoTextDefaults = {
  fallback: "linear-gradient(120deg, var(--rd-color-action-primary), var(--rd-color-feedback-info))",
  tone: "light",
  isPaused: false,
} as const;

export const videoTextMeta = {
  "name": "VideoText",
  "version": "0.1.0",
  "status": "experimental",
  "role": "text"
} as const;
